{"code":"import re
from collections import Counter

seq = open('region.fasta').read().split('\n',1)[1].replace('\n','')
seq_rc = seq.translate(str.maketrans("ACGT","TGCA"))[::-1]

codon_table = {
 'TTT':'F','TTC':'F','TTA':'L','TTG':'L','TCT':'S','TCC':'S','TCA':'S','TCG':'S',
 'TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','TGT':'C','TGC':'C','TGA':'*','TGG':'W',
 'CTT':'L','CTC':'L','CTA':'L','CTG':'L','CCT':'P','CCC':'P','CCA':'P','CCG':'P',
 'CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','CGT':'R','CGC':'R','CGA':'R','CGG':'R',
 'ATT':'I','ATC':'I','ATA':'I','ATG':'M','ACT':'T','ACC':'T','ACA':'T','ACG':'T',
 'AAT':'N','AAC':'N','AAA':'K','AAG':'K','AGT':'S','AGC':'S','AGA':'R','AGG':'R',
 'GTT':'V','GTC':'V','GTA':'V','GTG':'V','GCT':'A','GCC':'A','GCA':'A','GCG':'A',
 'GAT':'D','GAC':'D','GAA':'E','GAG':'E','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def translate(s, t=codon_table):
    bad=0
    aa=[]
    for i in range(0,len(s)-len(s)%3,3):
        c=t.get(s[i:i+3],'X')
        if c=='X': bad+=1
        aa.append(c)
    return ''.join(aa), bad

def orfs(s, minlen=150):
    stops = {'TAA','TAG','TGA'}
    prots=[]
    for strand,direction in [(s,'+'),(seq_rc,'-')]:
        L=len(strand)
        for frame in range(3):
            i=frame
            while i+3<=L:
                if strand[i:i+3]=='ATG':
                    j=i
                    aa=[]
                    while j+3<=L:
                        c=strand[j:j+3]
                        if c in stops:
                            break
                        aa.append(codon_table[c])
                        j+=3
                    if j+3<=L:  # ended at stop
                        prot=''.join(aa)
                        if len(prot)>=minlen:
                            prots.append((direction,frame+1,i+1,j+3-1-2,prot,c))
                    i=j+3
                else:
                    i+=3
    return prots

prots = orfs(seq, 100)
print("long ORFs (>=100 aa) with stop codon and ATG start:")
for p in prots:
    strand,frame,start,end,prot,stop = p
    print(f"  strand {'+' if strand=='+' else '-'} frame {frame}: nt {start}..{end}, len {len(prot)} aa (starts M, ends {stop})")
